/*
 * Bậc Thầy Đặt Tên (Lazy load kho ngữ liệu từ xa)
 * Tavern Helper / JS-Slash-Runner
 * Không đọc ngữ cảnh: Mỗi lần tạo cố định chèn 2 thời đại x 2 giới tính x 5 ứng viên = 20 tên.
 * Ngữ liệu được tải vào lần tạo đầu tiên, duy trì cache bộ nhớ và 30 ngày cache IndexedDB.
 * Phân nhóm giới tính dựa trên phỏng đoán dùng từ, không phải nhãn giới tính thực tế; vui lòng để model tự sàng lọc kết hợp cùng ngữ cảnh.
 */
(function () {
    'use strict';

    var KEY = 'name-generator-corpus-v3';
    var SUBSCRIPTION_KEY = '__name_generator_corpus_v3__';
    var REMOTE = {
        modern: 'https://raw.githubusercontent.com/YaoZeyuan/name-generator/master/resource/person_name/%E5%B7%B2%E7%9F%A5%E4%BA%BA%E5%90%8D.json',
        ancient: 'https://raw.githubusercontent.com/YaoZeyuan/name-generator/master/resource/old_person_name/%E4%B8%AD%E5%9B%BD%E5%8F%A4%E4%BB%A3%E4%BA%BA%E5%90%8D%E4%B8%8E%E5%AD%97-9336%E6%9D%A1-%E7%AE%80%E4%BD%93-opencc%E8%BD%AC%E6%8D%A2%E7%A8%BF_%E6%89%8B%E5%B7%A5%E6%9B%BF%E6%8D%A2_%E4%B9%BE%E5%B9%B2.json',
        attributes: 'https://raw.githubusercontent.com/yyz945947732/cnname/master/dict/words/attributes.json'
    };
    var commonSurnames = ['王','李','张','刘','陈','杨','黄','赵','周','吴','徐','孙','胡','朱','高','林','何','郭','马','罗','梁','宋','郑','谢','韩','唐','冯','于','董','萧','程','曹','袁','邓','许','傅','沈','曾','彭','吕','苏','卢','蒋','蔡','贾','丁','魏','薛','叶','阎','余','潘','杜','戴','夏','钟','汪','田','任','姜','范','方','石','姚','谭','廖','邹','熊','金','陆','郝','孔','白','崔','康','毛','邱','秦','江','史','顾','侯','邵','孟','龙','万','段','雷','钱','汤','尹','黎','易','常','武','乔','贺','赖','龚'];

    var eras = ['Cổ đại', 'Hiện đại'];
    var genders = ['Nam', 'Nữ'];
    var CANDIDATES_PER_GROUP = 5;
    var corpusPromise = null;
    var cacheClearPromise = null;
    var CACHE_DB = 'name-generator-corpus-cache';
    var CACHE_STORE = 'corpora';
    var CACHE_KEY = 'corpus-v2';
    var CACHE_TTL = 30 * 24 * 60 * 60 * 1000;

    function pick(list) { return list[Math.floor(Math.random() * list.length)]; }
    function cleanName(value) {
        return String(value || '').replace(/[^\u3400-\u9fff]/g, '');
    }
    function uniqueTwoChar(list) {
        var result = [], seen = {};
        (list || []).forEach(function (value) {
            if (typeof value !== 'string') return;
            var s = value.replace(/[^\u3400-\u9fff]/g, '');
            if (s.length === 2 && !seen[s]) { seen[s] = true; result.push(s); }
        });
        return result;
    }

    function sample(list, count, usedNames, era) {
        var result = [], tries = 0;
        if (!list || !list.length) return result;
        while (result.length < count && tries < count * 100) {
            var name = pick(list);
            if (era === 'Hiện đại') name = pick(commonSurnames) + name;
            if (name && !usedNames[name]) {
                usedNames[name] = true;
                result.push(name);
            }
            tries++;
        }
        return result;
    }
    function openCacheDb() {
        return new Promise(function (resolve) {
            var idb = globalThis.indexedDB;
            if (!idb) { resolve(null); return; }
            try {
                var request = idb.open(CACHE_DB, 1);
                request.onupgradeneeded = function () {
                    var db = request.result;
                    if (!db.objectStoreNames.contains(CACHE_STORE)) db.createObjectStore(CACHE_STORE);
                };
                request.onsuccess = function () { resolve(request.result); };
                request.onerror = function () { resolve(null); };
                request.onblocked = function () { resolve(null); };
            } catch (error) { resolve(null); }
        });
    }
    function readCachedCorpus() {
        return openCacheDb().then(function (db) {
            if (!db) return null;
            return new Promise(function (resolve) {
                try {
                    var tx = db.transaction(CACHE_STORE, 'readonly');
                    var request = tx.objectStore(CACHE_STORE).get(CACHE_KEY);
                    request.onsuccess = function () {
                        var entry = request.result;
                        var corpus = entry && entry.corpus;
                        if (entry && Date.now() - entry.savedAt < CACHE_TTL && corpus &&
                            Array.isArray(corpus.female) && Array.isArray(corpus.male) &&
                            Array.isArray(corpus.ancientFemaleNames) && Array.isArray(corpus.ancientMaleNames)) {
                            console.info('[Bậc Thầy Đặt Tên] Đã sử dụng cache ngữ liệu cục bộ.');
                            resolve(corpus);
                        } else resolve(null);
                    };
                    request.onerror = function () { resolve(null); };
                    tx.oncomplete = function () { db.close(); };
                    tx.onabort = function () { db.close(); resolve(null); };
                } catch (error) { db.close(); resolve(null); }
            });
        });
    }
    function writeCachedCorpus(corpus) {
        return openCacheDb().then(function (db) {
            if (!db) return;
            return new Promise(function (resolve) {
                try {
                    var tx = db.transaction(CACHE_STORE, 'readwrite');
                    var store = tx.objectStore(CACHE_STORE);
                    // Store này chỉ dùng cho script này; khi ghi ngữ liệu tinh gọn sẽ đồng thời xóa bản ghi phiên bản cũ.
                    store.clear();
                    store.put({ savedAt: Date.now(), corpus: corpus }, CACHE_KEY);
                    tx.oncomplete = function () { db.close(); resolve(); };
                    tx.onerror = function () { db.close(); resolve(); };
                    tx.onabort = function () { db.close(); resolve(); };
                } catch (error) { db.close(); resolve(); }
            });
        });
    }
    function fetchJson(url) {
        return fetch(url).then(function (response) {
            if (!response.ok) throw new Error('HTTP ' + response.status + ': ' + url);
            return response.json();
        });
    }
    function loadCorpus() {
        if (cacheClearPromise) return cacheClearPromise.then(loadCorpus);
        if (corpusPromise) return corpusPromise;
        corpusPromise = readCachedCorpus().then(function (cachedCorpus) {
            if (cachedCorpus) return cachedCorpus;
            return Promise.all([fetchJson(REMOTE.modern), fetchJson(REMOTE.ancient), fetchJson(REMOTE.attributes)]).then(function (data) {
            var modern = Object.keys(data[0] || {});
            var ancientRecords = [];
            (data[1] || []).forEach(function (row) {
                var surname = cleanName(row.char_姓氏);
                var given = cleanName(row.char_名);
                if ((surname.length === 1 || surname.length === 2) && (given.length === 1 || given.length === 2)) {
                    ancientRecords.push({ full: surname + given, given: given });
                }

            });
            var attributes = data[2] || {};
            var femaleChars = String(attributes.female || '');
            var maleChars = String(attributes.male || '');
            var female = uniqueTwoChar(modern.filter(function (name) {
                return name.split('').some(function (ch) { return femaleChars.indexOf(ch) >= 0; });
            }));
            var male = uniqueTwoChar(modern.filter(function (name) {
                return name.split('').some(function (ch) { return maleChars.indexOf(ch) >= 0; });
            }));
            var ancientFemaleNames = ancientRecords.filter(function (record) {
                return record.given.split('').some(function (ch) { return femaleChars.indexOf(ch) >= 0; });
            });
            var ancientMaleNames = ancientRecords.filter(function (record) {
                return record.given.split('').some(function (ch) { return maleChars.indexOf(ch) >= 0; });
            });
            return {
                ancientFemaleNames: ancientFemaleNames.map(function (record) { return record.full; }),
                ancientMaleNames: ancientMaleNames.map(function (record) { return record.full; }),
                female: female,
                male: male
            };
            }).then(function (corpus) {
                return writeCachedCorpus(corpus).then(function () { return corpus; });
            });
        }).catch(function (error) {
            console.error('[Bậc Thầy Đặt Tên] Tải kho ngữ liệu từ xa thất bại, sẽ sử dụng ngữ liệu dự phòng tích hợp sẵn.', error);
            return {

                female: uniqueTwoChar(['雨晴','诗涵','若溪','梦瑶','欣怡','雅婷','婉清','芷若','语嫣','可欣','静宜','雪宁']),
                male: uniqueTwoChar(['浩然','子轩','明远','承泽','景行','宇辰','知远','文博','修远','嘉言','景明','云舟']),
                ancientFemaleNames: ['李清照','班昭','蔡文姬','上官婉儿','谢道韫','鱼玄机','卓文君','花蕊夫人','薛涛','秦良玉','梁红玉','柳如是'],
                ancientMaleNames: ['李白','杜甫','苏轼','辛弃疾','诸葛亮','司马迁','王羲之','陶渊明','韩愈','柳宗元','欧阳修','陆游']
            };
        });
        return corpusPromise;
    }
    function clearCache() {
        if (cacheClearPromise) return cacheClearPromise;
        // Chờ quá trình tải và ghi đang diễn ra hoàn tất, tránh việc sau khi dọn dẹp yêu cầu cũ lại ghi đè cache trở lại.
        cacheClearPromise = Promise.resolve(corpusPromise).then(function () {
            corpusPromise = null;
            return openCacheDb();
        }).then(function (db) {
            if (!db) return false;
            return new Promise(function (resolve, reject) {
                try {
                    var tx = db.transaction(CACHE_STORE, 'readwrite');
                    tx.objectStore(CACHE_STORE).clear();
                    tx.oncomplete = function () { db.close(); resolve(true); };
                    tx.onabort = tx.onerror = function () { db.close(); reject(new Error('Dọn dẹp cache thất bại')); };
                } catch (error) { db.close(); reject(error); }
            });
        }).then(function (cleared) {
            cacheClearPromise = null;
            return cleared;
        }, function (error) {
            cacheClearPromise = null;
            throw error;
        });
        return cacheClearPromise;
    }
    function onCacheButtonClick(event) {
        var button = event.target && event.target.closest && event.target.closest('[data-qiming-clear-cache]');
        if (!button || button.disabled) return;
        var status = button.parentElement.querySelector('[data-qiming-cache-status]');
        button.disabled = true;
        if (status) status.textContent = 'Đang dọn dẹp...';
        clearCache().then(function (cleared) {
            if (status) status.textContent = cleared ? 'Cache đã được dọn dẹp, sẽ tải lại kho ngữ liệu vào lần tạo tiếp theo.' : 'Cache bộ nhớ đã được dọn dẹp; không thể truy cập cache liên tục, không thể xác nhận đã xóa hay chưa.';
        }, function (error) {
            if (status) status.textContent = 'Bộ nhớ đã được dọn dẹp, nhưng dọn dẹp cache liên tục thất bại, vui lòng thử lại.';
            console.error('[Bậc Thầy Đặt Tên] Dọn dẹp cache thất bại.', error);
        }).then(function () { button.disabled = false; });
    }
    function poolForEra(corpus, era, gender) {
        if (era === 'Hiện đại') return gender === 'Nữ' ? corpus.female : corpus.male;
        return gender === 'Nữ' ? corpus.ancientFemaleNames : corpus.ancientMaleNames;
    }
    function buildPrompt(corpus) {
        var lines = [
            '<name_candidates>',
            '<instruction>Các tên dưới đây chỉ là ứng viên tham khảo. Khi cốt truyện cần đặt tên, vui lòng kết hợp giới tính nhân vật, bối cảnh thời đại, thân phận và ngữ cảnh để tự phán đoán: Ưu tiên chọn các tên tự nhiên, phù hợp trong danh sách; nếu ứng viên không phù hợp, có thể viết lại hoặc tự nghĩ tên khác bám sát thiết lập hơn, không gượng ép áp dụng chỉ để dùng danh sách. Nếu cốt truyện hiện tại không cần đặt tên, vui lòng bỏ qua danh sách này, không đề cập hoặc xuất danh sách ứng viên.</instruction>',
            '<groups>'
        ];
        var usedNames = {};
        eras.forEach(function (era) {
            genders.forEach(function (gender) {
                var pool = poolForEra(corpus, era, gender);
                var names = sample(pool, CANDIDATES_PER_GROUP, usedNames, era);
                lines.push('<group era="' + era + '" gender="' + gender + '"><names>' + names.join(', ') + '</names></group>');
            });
        });
        lines.push('</groups>');
        lines.push('</name_candidates>');
        return lines.join(String.fromCharCode(10));
    }
    function injectNext() {
        return loadCorpus().then(function (corpus) {
            try { uninjectPrompts([KEY]); } catch (error) {}
            injectPrompts([{
                id: KEY,
                position: 'in_chat',
                depth: 0,
                role: 'system',
                content: buildPrompt(corpus),
                should_scan: false
            }], { once: true });
        });
    }
    var authorDocument = null;
    try {
        if (globalThis[SUBSCRIPTION_KEY] && typeof globalThis[SUBSCRIPTION_KEY].stop === 'function') globalThis[SUBSCRIPTION_KEY].stop();
        var subscription = eventOn(tavern_events.GENERATION_AFTER_COMMANDS, injectNext);
        // Ghi chú tác giả được trợ lý render trong popup của trang cha; ủy nhiệm sự kiện cũng hỗ trợ các ghi chú mở sau.
        try {
            authorDocument = parent.document;
            authorDocument.addEventListener('click', onCacheButtonClick);
        } catch (error) {
            console.info('[Bậc Thầy Đặt Tên] Nút ghi chú tác giả không khả dụng: Không thể truy cập trang cha.');
        }
        globalThis[SUBSCRIPTION_KEY] = { stop: function () {
            subscription.stop();
            if (authorDocument) authorDocument.removeEventListener('click', onCacheButtonClick);
        } };
        if (typeof window !== 'undefined') window.addEventListener('pagehide', function () {
            if (authorDocument) authorDocument.removeEventListener('click', onCacheButtonClick);
        }, { once: true });
        console.info('[Bậc Thầy Đặt Tên] Đã kích hoạt: Lazy load kho ngữ liệu từ xa, 4 nhóm cổ/hiện đại nam/nữ x 5 ứng viên.');
    } catch (error) {
        console.error('[Bậc Thầy Đặt Tên] Khởi tạo thất bại: Vui lòng xác nhận Tavern Helper / JS-Slash-Runner đã được bật.', error);
    }
})();
